// Üretilen dosya: tool/ozgun/uret.py. Biyoloji · Hücre organelleri ve zar taşıma ayrıntılı (zor).
const ozBiology6Zor = <(String, String, List<String>, String)>[
  ('1925\'te Gorter ve Grendel, alyuvar zarlarından çıkardıkları lipitleri su yüzeyine tek tabaka hâlinde yaydıklarında, kaplanan alanın alyuvarların toplam yüzey alanının yaklaşık iki katı olduğunu buldular. Bu sonuçtan hangi çıkarım yapılmıştır?', 'Zarın iki katlı bir lipit tabakası olduğu', ['Zarın tek kat lipitten oluştuğu', 'Zarın büyük kısmının proteinden yapıldığı', 'Zar lipitlerinin hücre yüzeyini tek ve kesintisiz bir tabakayla kapladığı'], 'Lipitler zarda iki katman hâlinde bulunuyorsa, tek tabaka olarak yayıldıklarında hücre yüzeyinin iki katı alan kaplarlar. Bu deney lipit çift katmanı fikrinin ilk deneysel dayanağıdır.'),
  ('Hücre zarındaki su kanallarını (akuaporinleri) keşfetmesiyle 2003 Nobel Kimya Ödülü\'nü alan bilim insanı kimdir?', 'Peter Agre', ['Jens Skou', 'Günter Blobel', 'Yoshinori Ohsumi'], 'Peter Agre akuaporinleri, Roderick MacKinnon ise iyon kanallarının yapısını aydınlatmış ve 2003 Nobel Kimya Ödülü\'nü paylaşmışlardır.'),
  ('Sodyum-potasyum pompası olarak çalışan Na⁺/K⁺-ATPaz enzimini keşfettiği için 1997 Nobel Kimya Ödülü\'nü paylaşan Danimarkalı bilim insanı kimdir?', 'Jens Christian Skou', ['Peter Mitchell', 'Christian de Duve', 'James Rothman'], 'Skou 1957\'de yengeç sinirlerinde Na⁺ ve K⁺ ile uyarılan ATPaz etkinliğini bulmuş, bu enzimin iyon pompası olduğunu göstermiştir.'),
  ('Hücre içinde keseciklerin doğru hedefe taşınmasını düzenleyen mekanizmaları aydınlattıkları için 2013 Nobel Fizyoloji veya Tıp Ödülü\'nü paylaşan üçlü hangisidir?', 'Rothman, Schekman ve Südhof', ['Watson, Crick ve Wilkins', 'Palade, Claude ve de Duve', 'Agre, MacKinnon ve Skou'], 'James Rothman, Randy Schekman ve Thomas Südhof kesecik trafiğinin genetik ve moleküler denetimini ortaya koymuştur.'),
  ('Diferansiyel santrifüjle elde edilen "mikrozom" kesiti çoğunlukla hangi yapıdan oluşur?', 'Parçalanmış ER zarlarının küçük keseciklerinden', ['Kromozomlardan', 'Bütün hâlinde kalmış, iç zar kıvrımları korunmuş mitokondrilerden', 'Hücre duvarı parçalarından'], 'Hücre parçalanırken ER zarları küçük kesecikler hâlinde kapanır; yüksek hızda çöken bu keseciklere mikrozom denir.'),
  ('Dondurarak kırma yöntemiyle hazırlanan zar örneklerinde, zarın iki lipit katmanı arasından ayrıldığı yüzeylerde küçük tümsekler görülür. Bu tümsekler neyin kanıtıdır?', 'Çift katmana gömülü integral proteinlerin', ['Zarda karbonhidrat bulunmadığının', 'Zarın tek katlı olduğunun', 'Kolesterolün zarın dış yüzeyinde ayrı bir tabaka hâlinde biriktiğinin'], 'Dondurulan zar, iki lipit tabakasının arasından ayrılır. Ortaya çıkan iç yüzeylerdeki tanecikler, çift katmanın içine gömülü integral proteinlerdir.'),
  ('Tek yağ asidi kuyruklu sabun molekülleri suda küçük küreler (misel) oluştururken, iki kuyruklu fosfolipitlerin çift katlı tabaka oluşturmasının nedeni nedir?', 'Molekül biçiminin düz tabakaya uygun olması', ['Fosfolipitlerin hiç su seven bölge taşımaması', 'Fosfolipitlerin zarda kovalent bağlarla birbirine bağlanması', 'Fosfolipitlerin yüksüz olması'], 'Tek kuyruklu moleküller koni biçimli olduğundan küre biçimli misellere uyar. İki kuyruklu fosfolipitlerin hacimli kuyruk kısmı silindire benzer ve en kararlı düzen iki katlı tabakadır.'),
  ('Hücre zarının iç ve dış katmanlarında farklı lipitlerin bulunmasını sürdüren ve fosfolipitleri ATP harcayarak bir katmandan diğerine taşıyan enzimlere genel olarak ne ad verilir?', 'Flipazlar', ['Lipazlar', 'Helikazlar', 'Proteazlar'], 'Flipazlar belirli fosfolipitleri, özellikle fosfatidilserini, zarın sitoplazmaya bakan yüzünde tutarak zar asimetrisini korur.'),
  ('Hücre zarında kolesterol ve sfingolipitlerce zengin, çevresine göre daha düzenli ve daha az akışkan olan, bazı sinyal proteinlerini bir araya toplayan küçük bölgelere ne ad verilir?', 'Lipit salları', ['Akuaporinler', 'Desmozomlar', 'Plazmodezmata'], 'Lipit salları belirli reseptör ve sinyal proteinlerinin bir arada bulunmasını kolaylaştıran geçici mikrobölgelerdir.'),
  ('Hücre zarındaki bir proteinin, zarın içine hiç girmeden yalnız zarın dış yüzündeki özel bir glikolipite (GPI çapası) kovalent bağla tutunması onu hangi gruba sokar?', 'Lipitle çapalanmış zar proteinleri', ['Lipit çift katmanını birkaç kez boydan boya geçen transmembran kanal proteinleri', 'Hücre iskeleti proteinleri', 'Çekirdek proteinleri'], 'Bazı zar proteinleri polipeptit zinciriyle değil, kovalent bağlandıkları bir lipit kuyruğuyla zara tutunur; GPI çapalı proteinler bunun örneğidir.'),
  ('Gram negatif bakterilerin dış zarında ve mitokondrilerin dış zarında bulunan, küçük moleküllerin geçebileceği geniş gözenekler oluşturan beta-varil biçimli proteinlere ne ad verilir?', 'Porinler', ['Akuaporinler', 'Kaderinler', 'Aktinler'], 'Porinler, beta tabakalarının bir fıçı gibi kıvrılmasıyla oluşan geniş kanallardır; bu yüzden mitokondri dış zarı küçük moleküllere karşı oldukça geçirgendir.'),
  ('Geçit (gap) bağlantılarının kanallarını oluşturan protein alt birimlerine ne ad verilir?', 'Konneksin', ['Kaderin', 'İntegrin', 'Klatrin'], 'Altı konneksin bir yarım kanal (konnekson) oluşturur; iki komşu hücrenin konneksonları birleşince hücreler arası kanal oluşur.'),
  ('Desmozomlarda iki komşu hücrenin hücre iskeletleri bağlantı plaklarıyla birbirine bağlanır. Bu plaklara hücre içinden bağlanan iskelet elemanı hangisidir?', 'Ara filamentler', ['Mikrotübüller', 'Aktin mikrofilamentleri', 'Sentriyoller'], 'Desmozom plaklarına keratin gibi ara filamentler bağlanır; bu lifler dokuya çekme kuvvetlerine karşı direnç kazandırır.'),
  ('Komşu hücrelerin zarlarını birbirine bağlayan ve işlev görebilmek için ortamda kalsiyum iyonlarına gereksinim duyan hücre yapışma proteinleri hangileridir?', 'Kaderinler', ['Konneksinler', 'Akuaporinler', 'Histonlar'], 'Kaderin adı "kalsiyuma bağımlı yapışma" anlamından gelir. Ortamdaki kalsiyum uzaklaştırıldığında kaderinlerle tutunan hücreler birbirinden ayrılır.'),
  ('Hücre zarında bulunup bir uçtan hücre dışı matriksteki fibronektin gibi proteinlere, diğer uçtan hücre içindeki aktin iskeletine bağlanan reseptör proteinlerine ne ad verilir?', 'İntegrinler', ['Kaderinler', 'Konneksinler', 'Porinler'], 'İntegrinler dış matriks ile iç iskelet arasında köprü kurar; matriksten gelen mekanik ve kimyasal bilgileri hücre içine iletir.'),
  ('Kalın ikincil duvarlarda, komşu hücreler arasında madde geçişinin sürmesini sağlayan ve ikincil duvarın oluşmadığı ince bölgelere ne ad verilir?', 'Geçitler (pitler)', ['Çekirdek porları', 'Lentiseller (kovucuklar)', 'Stomalar'], 'İkincil duvarın bırakılmadığı bu ince alanlarda yalnız birincil duvar ve orta lamel bulunur; su ve maddeler bu geçitlerden komşu hücreye kolayca geçer.'),
  ('Gram negatif bakterilerin ince peptidoglikan tabakasının dışında bulunan dış zarın yapısında yer alan ve vücuda girdiğinde ateş ve şok yapabilen bileşen hangisidir?', 'Lipopolisakkarit', ['Teikoik asit polimerleri', 'Ergosterol', 'Kitin'], 'Gram negatif bakterilerin dış zarındaki lipopolisakkaritler endotoksin olarak bilinir; bakteri parçalandığında açığa çıkarak güçlü bağışıklık tepkilerine yol açar.'),
  ('Gram pozitif bakterilerin kalın peptidoglikan tabakası içinde bulunan ve Gram negatiflerde görülmeyen karakteristik bileşen hangisidir?', 'Teikoik asitler', ['Lipopolisakkaritler', 'Porinler', 'Dış zar'], 'Teikoik asitler Gram pozitif çeperin peptidoglikanına bağlı polimerlerdir. Dış zar, porinler ve lipopolisakkarit ise Gram negatif bakterilere özgüdür.'),
  ('Potasyum kanalları K⁺ iyonlarını saniyede milyonlarca geçirirken kendisinden daha küçük olan Na⁺ iyonlarını neredeyse hiç geçirmez. Bu seçiciliğin temel nedeni nedir?', 'Süzgecin K⁺ iyonunun su kılıfını tam karşılaması', ['Na⁺ iyonlarının K⁺ iyonlarından daha büyük olup kanala sığmaması', 'Na⁺ iyonlarının negatif yüklü olması', 'Kanalın ATP\'yi yalnız K⁺ için harcaması'], 'Süzgeçteki oksijen atomları K⁺ iyonunu su kılıfından soyulmuş hâlde tam sarar. Daha küçük Na⁺ iyonu bu oksijenlerle yeterince etkileşemediği için su kılıfını bırakmaz ve geçemez.'),
  ('Akuaporin kanallarının saniyede milyarlarca su molekülünü geçirdiği hâlde H⁺ iyonlarının (protonların) geçişine izin vermemesinin hücre için önemi nedir?', 'Proton farklarının bozulmasını önlemesi', ['Hücreye su girişini tamamen durdurması', 'Suyun hücreden yalnızca dışarı çıkmasını, içeri girmemesini sağlaması', 'Hücre içindeki şekeri dışarı atması'], 'Protonlar geçebilseydi hücrelerdeki önemli H⁺ gradyanları ve pH dengesi bozulurdu. Akuaporinlerin yapısı su moleküllerinin dizisi boyunca proton aktarımını engeller.'),
  ('Valinomisin adlı antibiyotik, K⁺ iyonlarını sarıp lipit çift katmanının içinden taşıyan küçük bir moleküldür. Bu tür moleküllere ne ad verilir?', 'İyonofor', ['Akuaporin', 'Lizozim', 'Konneksin'], 'İyonoforlar iyonların zardan geçişini kolaylaştıran küçük moleküllerdir; valinomisin taşıyıcı, gramisidin ise kanal oluşturan iyonofor örneğidir.'),
  ('Van \'t Hoff bağıntısına (π = MRT) göre 27 °C\'de 0,1 M glikoz çözeltisinin osmotik basıncı yaklaşık kaç atmosferdir? (R = 0,082 L·atm/mol·K)', '2,46 atm', ['0,22 atm', '24,6 atm', '0,82 atm'], 'T = 27 + 273 = 300 K. π = 0,1 × 0,082 × 300 = 2,46 atm. Glikoz iyonlaşmadığı için tanecik sayısı çarpanı 1\'dir.'),
  ('Alyuvarlar, osmotik derişimi kan plazmasıyla aynı olan bir üre çözeltisine konduğunda bir süre sonra şişip patlıyor. Bunun nedeni nedir?', 'Ürenin zardan hücreye girip suyu da içeri çekmesi', ['Ürenin hücre zarını kimyasal olarak eritmesi', 'Çözeltinin alyuvara göre hipertonik olması', 'Ürenin hemoglobini parçalaması'], 'Osmotik derişim başlangıçta eşittir; ancak zar üreyi geçirdiği için üre hücreye girer, hücre içi tanecik derişimi artar ve su osmozla içeri dolar. Bu yüzden çözelti işlevsel olarak hipotoniktir.'),
  ('Sodyum-potasyum pompası ATP\'yi parçaladığında fosfat grubu doğrudan pompanın kendisine bağlanır ve pompa biçim değiştirir. Bu tür pompalar genel olarak nasıl sınıflandırılır?', 'P tipi ATPazlar', ['V tipi ATPazlar', 'ATP sentazlar', 'Porinler'], 'P tipi pompalar taşıma döngüsünde kendilerini fosforlar (fosforile olur); Na⁺/K⁺ ve Ca²⁺ pompaları bu gruptandır. V tipi pompalar ise lizozom gibi keseciklerin içini asitleştirir.'),
  ('Yüksük otundan (Digitalis) elde edilen digoksin Na⁺/K⁺ pompasını kısmen baskılar ve kalp kasının kasılma gücünü artırır. Bu etkinin zar taşıma düzeyindeki açıklaması nedir?', 'Hücrede Na⁺ artınca Na⁺/Ca²⁺ değiştiricisi daha az Ca²⁺ dışarı atar', ['Pompanın durmasıyla hücre içinde ATP sentezinin artması', 'Digoksinin Ca²⁺ kanallarını kalıcı olarak kapatması', 'K⁺ iyonlarının kas hücresinde birikip kasılmayı doğrudan tetiklemesi'], 'Na⁺/Ca²⁺ değiştiricisi Ca²⁺\'u dışarı atmak için içeri akan Na⁺\'un enerjisini kullanır. İçerideki Na⁺ artınca bu akış zayıflar, hücrede daha fazla Ca²⁺ kalır ve kasılma güçlenir.'),
  ('Reseptör aracılı endositozda zarın iç yüzünü kaplayarak çukurun oluşmasına ve keseciğin şekillenmesine yardım eden, üç kollu birimlerden kafes oluşturan protein hangisidir?', 'Klatrin', ['Kaderin', 'Tübülin', 'Kollajen'], 'Klatrin molekülleri zarın sitoplazma tarafında sepet benzeri bir kafes kurar; reseptörlerin toplandığı bu bölgeler klatrin kaplı çukurlar olarak içeri kıvrılır.'),
  ('Endositozla oluşan keseciğin hücre zarından koparak ayrılması sırasında keseciğin boynunu sararak boğan GTP\'az proteini hangisidir?', 'Dinamin', ['Aktin', 'Kinezin', 'Akuaporin'], 'Dinamin halkalar hâlinde kesecik boynunu sarar ve GTP enerjisiyle sıkıştırarak keseciğin zardan ayrılmasını sağlar.'),
  ('Reseptör aracılı endositozla alınan maddeler önce iç kısmı hafif asidik olan keseciklere ulaşır; burada madde reseptörden ayrılır ve reseptörler zara geri gönderilir. Bu keseciklere ne ad verilir?', 'Erken endozom', ['Peroksizom', 'Salgı keseciği', 'Glioksizom'], 'Erken endozomların asidik ortamı birçok ligandın reseptöründen ayrılmasını sağlar; boşalan reseptörler zara döner, madde ise geç endozom ve lizozom yoluna devam eder.'),
  ('Hücre zarında küçük, şişe biçimli çöküntüler oluşturan ve kaveolin proteiniyle tanımlanan, kolesterolce zengin endositoz yapılarına ne ad verilir?', 'Kaveola', ['Desmozom', 'Plazmodezma', 'Mikrovillus'], 'Kaveolalar lipit sallarıyla ilişkili küçük zar çöküntüleridir; bazı maddelerin alınmasında ve sinyal iletiminde görev alır, özellikle damar iç yüzeyi hücrelerinde boldur.'),
  ('Taşıma keseciğinin doğru hedef zarı tanıyıp onunla kaynaşmasını sağlayan, keseciğin ve hedef zarın üzerinde birbirine sarılan eşleşmiş proteinlere genel olarak ne ad verilir?', 'SNARE proteinleri', ['Histon proteinleri', 'Akuaporinler', 'Kaderinler'], 'Keseciğin üzerindeki v-SNARE ile hedef zardaki t-SNARE birbirine sarılarak iki zarı yaklaştırır ve kaynaşmayı sağlar; bu eşleşme kesecik trafiğinin özgüllüğüne de katkı yapar.'),
  ('Çocuklukta hızlı yaşlanma belirtileriyle seyreden Hutchinson-Gilford progeria sendromunda bozuk olan protein çekirdeğin hangi yapısında görev alır?', 'Çekirdek laminası', ['Çekirdekçik', 'Çekirdek porunun merkezi kanalı', 'Kromozomların uç kısımları'], 'Bu sendrom lamin A geninin mutasyonundan kaynaklanır; bozuk lamin çekirdek biçimini ve işlevini bozarak erken yaşlanmaya yol açar.'),
  ('Kloroplasta gidecek ve çekirdek genlerince şifrelenen proteinlerin ucunda bulunan, kloroplast zarlarındaki taşıyıcılar tarafından tanınan diziye ne ad verilir?', 'Transit peptit', ['Kodon', 'Sentromer', 'Telomer dizisi'], 'Kloroplast proteinlerinin çoğu çekirdekte şifrelenir; uçlarındaki transit peptit sayesinde sitoplazmadan kloroplast içine aktarılır ve bu dizi içeride kesilir.'),
  ('Bakteri ribozomu 30S ve 50S alt birimlerinden oluştuğu hâlde bütün ribozomun 80S değil 70S olarak ölçülmesinin nedeni nedir?', 'Çökme katsayısının kütleyle birlikte biçime de bağlı olması', ['Alt birimlerden birinin ölçüm sırasında parçalanması', 'Ribozomların ağırlığının ölçülememesi', 'Bir alt birimin RNA\'sını kaybetmesi'], 'Svedberg birimi (S) santrifüjde çökme hızını gösterir; bu hız kütle kadar molekülün biçimine ve yüzeyine de bağlı olduğundan alt birimlerin değerleri toplanmaz.'),
  ('Ökaryot ribozomlarındaki rRNA türlerinin sayısı ile bakteri ribozomlarındakiler karşılaştırıldığında hangisi doğrudur?', 'Ökaryotlarda 4, bakterilerde 3 tür rRNA bulunur', ['İkisinde de yalnız 1 tür rRNA bulunur', 'Bakterilerde 4, ökaryotlarda 3 tür rRNA bulunur', 'Ökaryot ribozomlarında rRNA bulunmaz, yalnız protein bulunur'], 'Bakteri ribozomunda 16S, 23S ve 5S; ökaryot ribozomunda ise 18S, 28S, 5,8S ve 5S rRNA\'ları bulunur.'),
  ('Proteinlerin içinde kendi hücresel adreslerini belirleyen sinyal dizileri taşıdığını öne süren "sinyal hipotezi" ile 1999 Nobel Fizyoloji veya Tıp Ödülü\'nü alan bilim insanı kimdir?', 'Günter Blobel', ['George Palade', 'Christian de Duve', 'Peter Mitchell'], 'Blobel, proteinlerin ER\'ye ve diğer bölmelere yönlendirilmesini sağlayan sinyal dizilerini tanımlamıştır.'),
  ('Granüllü ER\'de proteinlere eklenen şeker zincirleri için hangisi doğrudur?', 'Hazır bir oligosakkarit bloğu olarak aktarılır', ['Şekerler çekirdekte tek tek eklenir ve protein porlardan dışarı çıkar', 'Şeker eklenmesi yalnız hücre dışında olur', 'Bu proteinlere hiçbir zaman şeker eklenmez'], 'ER\'de, bir lipit taşıyıcı üzerinde önceden kurulmuş dallı bir oligosakkarit bloğu proteindeki asparagin amino asidine aktarılır; bu zincir daha sonra Golgi\'de düzenlenir.'),
  ('Karaciğer hücrelerinde glikojenin yıkımından oluşan glikoz-6-fosfatın fosfatını kopararak serbest glikozun kana verilmesini sağlayan enzim hangi organelin zarında bulunur?', 'Düz ER', ['Golgi cisimciği', 'Lizozom', 'Peroksizom'], 'Glikoz-6-fosfataz düz ER zarına bağlı bir enzimdir; fosfatlı glikoz zardan geçemezken serbest glikoz hücreden çıkıp kana karışabilir.'),
  ('Lizozoma gidecek enzimlerin Golgi\'de tanınıp ayrılmasını sağlayan kimyasal işaret hangisidir?', 'Mannoz-6-fosfat', ['Ubikitin zinciri', 'Çekirdek yerleşim sinyali', 'Transit peptit'], 'Golgi\'de lizozom enzimlerinin şeker zincirindeki mannoz birimlerine fosfat eklenir; trans Golgi\'deki reseptörler bu işareti tanıyıp enzimleri lizozoma giden keseciklere yönlendirir.'),
  ('ER\'den Golgi\'ye ileri yönde, Golgi\'den ER\'ye ise geri yönde madde taşıyan kesecikleri kaplayan proteinler sırasıyla hangileridir?', 'COPII ve COPI', ['COPI ve COPII', 'Klatrin ve kaveolin', 'Aktin ve miyozin'], 'COPII kaplı kesecikler ER\'den çıkıp Golgi\'ye gider; COPI kaplı kesecikler ise Golgi\'den ER\'ye geri dönüş taşımasını yapar.'),
  ('Brefeldin A adlı madde ER\'den Golgi\'ye kesecik taşınmasını engellediğinde, birkaç dakika içinde Golgi zarlarının ER ile karışıp Golgi\'nin dağıldığı görülür. Bu sonuç Golgi hakkında neyi gösterir?', 'Sürekli kesecik akışıyla süren dinamik bir yapı olduğunu', ['Golgi\'nin ER\'den tamamen bağımsız sabit bir organel olduğunu', 'Golgi\'nin yalnız bitki hücrelerinde bulunduğunu', 'Golgi\'nin kendi DNA\'sıyla bölünerek çoğaldığını'], 'Golgi\'ye gelen ve oradan çıkan kesecik dengesi bozulunca organel korunamaz; bu, Golgi\'nin sürekli yenilenen dinamik bir bölme olduğunu gösterir.'),
  ('Tay-Sachs hastalığında bir lizozom enziminin eksikliği nedeniyle sinir hücrelerinde birikerek ağır nörolojik bozukluklara yol açan madde grubu hangisidir?', 'Gangliozitler', ['Glikojen', 'Kolesterol', 'Kollajen'], 'Tay-Sachs hastalığında heksozaminidaz A enzimi eksiktir; sinir hücresi zarlarının bileşeni olan GM2 gangliozidi yıkılamaz ve lizozomlarda birikir.'),
  ('Pompe hastalığında asit maltaz adlı lizozom enzimi eksik olduğundan özellikle kas hücrelerinin lizozomlarında hangi madde birikir?', 'Glikojen', ['Gangliozit', 'Kolesterol', 'Ürik asit'], 'Pompe hastalığı bir glikojen depo hastalığıdır; lizozoma alınan glikojen yıkılamadığı için kalp ve iskelet kası hücrelerinde birikir ve kas güçsüzlüğüne yol açar.'),
  ('Sinir ve kalp kası hücreleri gibi uzun ömürlü ve bölünmeyen hücrelerde yaşla birlikte biriken, sindirilemeyen kalıntılar içeren sarı-kahverengi "yaşlılık pigmenti" hangisidir?', 'Lipofuskin', ['Melanin', 'Klorofil', 'Hemoglobin ve türevleri'], 'Lipofuskin, lizozomlarda tam sindirilemeyen lipit ve protein kalıntılarından oluşur; bölünmeyen hücrelerde dışarı atılamadığı için yaşla birikir.'),
  ('Bazı süs bitkilerinin (örneğin difenbahya) yaprağı çiğnendiğinde ağızda yanma ve şişme olmasının nedeni, hücrelerindeki iğne biçimli kristallerdir. Bu kristaller hangi maddeden oluşur ve nerede bulunur?', 'Kalsiyum oksalat; kofulda', ['Sodyum klorür; hücre duvarında', 'Glikoz; kloroplastta', 'Selüloz; çekirdekte'], 'Rafit denen iğne biçimli kalsiyum oksalat kristalleri özel hücrelerin kofullarında oluşur; otçulların ağız dokusuna batarak savunma sağlar.'),
  ('Mitokondri iç zarında bol bulunan ve başka hücre zarlarında pek görülmeyen, dört yağ asidi zincirli özel fosfolipit hangisidir?', 'Kardiyolipin', ['Kolesterol', 'Sfingomiyelin', 'Ergosterol'], 'Kardiyolipin, iç zarın protonlara karşı geçirgenliğinin düşük kalmasına ve solunum enzimlerinin bir arada durmasına katkı yapar; bakteri zarlarında da bulunur.'),
  ('İnsan mitokondri DNA\'sındaki 37 genin şifrelediği ürünler için hangisi doğrudur?', '13\'ü protein, geri kalanı tRNA ve rRNA\'dır', ['Tamamı mitokondri dış zarındaki porin proteinleridir', 'Tamamı çekirdek DNA\'sının eşlenmesinde görev alan enzimlerdir', 'Yalnızca hücre zarı reseptörlerini şifreler'], 'Mitokondri DNA\'sı 13 solunum zinciri proteini, 22 tRNA ve 2 rRNA şifreler; mitokondri proteinlerinin geri kalanı çekirdek genlerinden gelir.'),
  ('Bir hücrede hem normal hem de mutasyonlu mitokondri DNA\'larının bir arada bulunmasına ne ad verilir ve bu durum hastalığın belirtileriyle nasıl ilişkilidir?', 'Heteroplazmi; mutant oranı belirleyicidir', ['Homozigotluk; belirtiler hiçbir zaman ortaya çıkmaz', 'Poliploidi; hücre bölünmesi durur', 'Kodominantlık; iki fenotip eşit görülür'], 'Hücrede yüzlerce mitokondri DNA kopyası bulunur. Bozuk kopyaların oranı dokudan dokuya ve bireyden bireye değiştiği için aynı mutasyon farklı ağırlıkta belirtilere yol açabilir.'),
  ('Mitokondrilerin atası olarak kabul edilen bakteri grubu hangisidir?', 'Alfa-proteobakteri', ['Siyanobakteriler', 'Spiroketler', 'Arkeler'], 'Mitokondri genomu ve proteinleri, bugünkü Rickettsia gibi alfa-proteobakterilerle en yakın akrabalığı gösterir.'),
  ('Mikrotübüllerin bir ucunun sürekli uzayıp kısalarak hızla büyüme ve ani çökme dönemleri arasında gidip gelmesine ne ad verilir?', 'Dinamik kararsızlık', ['Turgor', 'Zar asimetrisi', 'Plazmoliz'], 'Dinamik kararsızlık mikrotübüllerin hücre içini hızla taramasını ve iğ iplikleri gibi geçici yapıların çabuk kurulup sökülmesini sağlar; olay tübüline bağlı GTP\'nin yıkımıyla ilişkilidir.'),
  ('Bazı balıkların derisindeki pigment hücrelerinde, siyah pigment tanecikleri bir uyarıyla hücre merkezinde toplanıp balığın açık renk görünmesine, başka bir uyarıyla hücreye yayılıp koyulaşmasına yol açar. Bu taneciklerin hareketi neye dayanır?', 'Mikrotübüller boyunca motor proteinlerle taşınmalarına', ['Kofulun su alıp vermesine', 'Taneciklerin hücre zarından dışarı çıkmasına', 'Pigmentin her seferinde yeniden sentezlenmesine'], 'Pigment tanecikleri dinein ile merkeze toplanır, kinezin ile çevreye dağıtılır; böylece balık rengini dakikalar içinde değiştirebilir.'),
  ('Silin içindeki dinein kolları komşu mikrotübül çiftlerini birbirine göre kaydırmaya çalışır. Bu kayma hareketinin silin bükülmesine dönüşmesini sağlayan nedir?', 'Çiftleri birbirine bağlayan esnek protein köprüleri', ['Silin hücre zarından ayrılması', 'Merkezdeki mikrotübüllerin çözünmesi', 'Bazal cismin dönmesi'], 'Mikrotübül çiftleri nexin gibi proteinlerle birbirine bağlı olduğundan serbestçe kayamaz; kayma kuvveti bu yüzden silin bükülmesine dönüşür.'),
  ('Bakteri kamçısının tabanındaki dönen motor çalışmak için doğrudan hangi enerji kaynağını kullanır?', 'Zar boyunca oluşmuş H⁺ (proton) akışını', ['Kamçının ucundaki ATP depolarını', 'Işık enerjisini', 'Hücre duvarındaki şekerlerin yıkımını'], 'Bakteri kamçı motoru, protonların zar boyunca derişim farkı yönünde akışından enerji alır; bazı türlerde bu işi Na⁺ akışı yapar.'),
  ('Bazı sucul bakteriler hücreleri içindeki zarla çevrili küçük demir mineral (manyetit) kristalleri sayesinde Dünya\'nın manyetik alanına göre yönlenir. Bu yapılara ne ad verilir?', 'Manyetozom', ['Mezozom', 'Karboksizom', 'Nükleoit'], 'Manyetozomlar zarla sarılı manyetit kristalleridir; bakteri bunlar sayesinde pusula iğnesi gibi yönlenerek uygun oksijen düzeyindeki su katmanlarını bulur.'),
  ('Arke zar lipitlerini bakteri ve ökaryot zar lipitlerinden ayıran kimyasal özellik hangisidir?', 'Zincirlerin gliserole eter bağıyla bağlanması', ['Zincirlerin gliserole peptit bağıyla bağlanması', 'Hiç gliserol içermemeleri', 'Yalnızca kolesterolden oluşmaları'], 'Bakteri ve ökaryotlarda yağ asitleri gliserole ester bağıyla, arkelerde ise dallanmış izoprenoit zincirleri eter bağıyla bağlanır; eter bağı aşırı sıcaklıkta daha dayanıklıdır.'),
  ('Çok yüksek sıcaklıkta yaşayan bazı arkelerin zarında, iki katman yerine zarı boydan boya geçen tek katlı lipitler bulunur. Bu yapının sağladığı yarar nedir?', 'Zarın sıcakta ayrışmaması', ['Zarın soğukta akışkanlaşması', 'Hücreye ışık soğurma ve fotosentez yapma yeteneği kazandırması', 'Zardan su geçişini artırması'], 'İki ucu da polar olan uzun tetraeter lipitleri zarın iki yüzünü kovalent olarak bağlar; böylece sıcaklıkta katmanların birbirinden ayrılması önlenir.'),
  ('Sinir hücrelerinin gövdesinde ışık mikroskobuyla koyu boyanan kümeler hâlinde görülen Nissl cisimcikleri aslında hangi yapının yoğunlaştığı bölgelerdir?', 'Granüllü ER yığınları', ['Mitokondriler', 'Lizozomlar', 'Golgi cisimcikleri ve salgı kesecikleri'], 'Nissl cisimcikleri bol ribozomlu granüllü ER yığınlarıdır; nöronların sinir ileticisi ve zar proteini üretimindeki yüksek protein sentezini yansıtır.'),
  ('Yarıçapı 10 µm olan küresel bir hücre, her birinin yarıçapı 0,05 µm olan salgı keseciklerini ekzositozla boşaltıyor. Hücre zarının yüzey alanının iki katına çıkması için yaklaşık kaç kesecik zarı eklenmelidir? (Küre yüzeyi = 4πr²)', '40 000', ['200', '4000', '400 000'], 'Yüzeylerin oranı (10 / 0,05)² = 200² = 40 000\'dir. Zarın iki katına çıkması için hücre yüzeyine eşit miktarda zar, yani yaklaşık 40 000 kesecik gerekir.'),
  ('Plazmodezmaların ortasından geçen ve iki komşu hücrenin endoplazmik retikulumlarını birbirine bağlayan ince zar tüpüne ne ad verilir?', 'Desmotübül', ['Mikrotübül', 'Tonoplast', 'Granum'], 'Plazmodezma kanalı hücre zarıyla döşelidir; ortasında ER\'nin devamı olan desmotübül bulunur ve madde geçişi bu ikisi arasındaki sitoplazmik halkadan olur.'),
  ('Ayçiçeği ve kolza gibi yağlı tohumların hücrelerinde yağlar, tek katlı bir fosfolipit zarla çevrili küçük damlacıklar hâlinde depolanır. Bu yapılara ne ad verilir?', 'Oleozom', ['Lizozom', 'Amiloplast taneleri', 'Peroksizom'], 'Oleozomlar ER\'den köken alan, tek katmanlı fosfolipit ve oleozin proteiniyle kaplı yağ damlacıklarıdır; çimlenmede glioksizomlarla birlikte yağların kullanılmasını sağlar.'),
  ('Canlı hücrelerde mitokondrileri seçici olarak boyamak için kullanılan ve hücreyi öldürmeden uygulanabilen boya hangisidir?', 'Janus yeşili B', ['Sudan III', 'İyot çözeltisi', 'Biüret ayıracı'], 'Janus yeşili B, mitokondrilerdeki etkin enzimler sayesinde renkli kalan bir canlı (vital) boyadır; bu yüzden mitokondrileri canlı hücrede görünür kılar.'),
  ('Bitki hücrelerinin kofullarını canlı hücrede seçici olarak boyamak için kullanılan ve asidik ortamda kırmızı renk veren boya hangisidir?', 'Nötral kırmızı', ['Janus yeşili B', 'Metilen mavisi', 'Sudan III'], 'Nötral kırmızı zayıf bazik bir canlı boyadır; asidik koful içinde birikip kırmızıya döner ve kofulları belirginleştirir.'),
  ('İlk elektron mikroskobunu 1930\'ların başında geliştiren ve bu çalışması için 1986\'da Nobel Fizik Ödülü\'nü paylaşan bilim insanı kimdir?', 'Ernst Ruska', ['Robert Hooke', 'Antonie van Leeuwenhoek', 'Frits Zernike'], 'Ernst Ruska ve Max Knoll ilk elektron mikroskobunu 1931\'de geliştirdi; Ruska 1986\'da Nobel Fizik Ödülü\'nün yarısını aldı. Zernike ise faz kontrast mikroskobunun mucididir.'),
  ('Mikrotübüllerin sentrozomda kurulmaya başlamasını sağlayan, tübülin ailesinin üçüncü üyesinden oluşan halka yapılar hangisidir?', 'Gama tübülin halkaları', ['Aktin halkaları', 'Kaderin halkaları', 'Lamin halkaları'], 'Sentrozomun çevresindeki maddede bulunan gama tübülin halka kompleksleri yeni mikrotübüllerin çekirdeklenme noktası işlevi görür.'),
  ('Zarı yedi kez boydan boya geçen ve sinyal molekülü bağlanınca hücre içinde bir G proteinini etkinleştiren reseptörlere ne ad verilir?', 'G proteinine bağlı reseptörler', ['İyon kanalı reseptörleri', 'Çekirdekteki hücre içi steroit reseptörleri', 'Tirozin kinaz reseptörleri'], 'Bu reseptörler sinyali alınca biçim değiştirir ve zarın iç yüzündeki G proteinini etkinleştirir; koku, ışık algısı ve pek çok hormon bu yolla işler.'),
  ('Bazı büyüme faktörlerinin reseptörleri sinyal bağlandığında iki reseptör molekülünün yan yana gelip birbirlerine fosfat eklemesiyle etkinleşir. Bu reseptörler hangi gruptadır?', 'Tirozin kinaz reseptörleri', ['G proteinine bağlı reseptörler', 'Akuaporinler', 'Ligand kapılı kanallar'], 'Tirozin kinaz reseptörleri eşleşip birbirlerinin tirozin amino asitlerini fosforlar; bu fosfatlı bölgeler hücre içindeki sinyal proteinlerini etkinleştirir.'),
  ('Bir araştırmacı bir maddenin hücreye aktif taşımayla girip girmediğini test etmek istiyor. Hangi deney düzeni bu soruyu en iyi yanıtlar?', 'Solunum zehirli ve zehirsiz grupları karşılaştırmak', ['Hücreyi yalnız mikroskopta incelemek', 'Hücrenin çevresindeki suyu ısıtıp rengindeki değişimi gözlemlemek', 'Maddeyi hücresiz bir sıvıya koyup bekletmek'], 'Aktif taşımada madde derişim farkına karşı birikir ve bu birikim ATP üretimi engellenince durur. Zehirli ve zehirsiz grupların karşılaştırılması bu iki özelliği birlikte sınar.'),
  ('Bir maddenin hücre içinde dış ortamdan çok daha yüksek derişime ulaştığını gören bir öğrenci "Bu madde kesinlikle aktif taşımayla girmiştir" sonucuna varıyor. Bu sonuç neden aceleci olabilir?', 'Madde içeride bağlanıp tutuluyor olabilir', ['Hücre içindeki derişim hiçbir zaman ölçülemez', 'Aktif taşıma maddeleri yalnız hücreden dışarı taşır', 'Difüzyon her zaman hücre içinde dışarıdakinden daha yüksek derişim oluşturur'], 'Toplam derişim yüksek görünse de madde proteinlere bağlanıyor ya da başka bir moleküle dönüştürülüyorsa serbest hâldeki derişimi düşük kalır ve giriş pasif olabilir.'),
  ('Proteinlerin çekirdeğe alınıp çekirdekten çıkarılmasının yönünü belirleyen başlıca etken hangisidir?', 'Ran-GTP/Ran-GDP derişim farkı', ['Çekirdeğin sitoplazmadan daha sıcak olması', 'Por kompleksinin yalnız tek yönde açılması', 'Çekirdek zarındaki aktin ipliklerinin kasılması'], 'Ran proteininin GTP\'li biçimi çekirdekte, GDP\'li biçimi sitoplazmada bol bulunur; bu fark taşıyıcıların yükü bir tarafta alıp öbür tarafta bırakmasını ve taşımanın yönlü olmasını sağlar.'),
  ('Kloroplast ile mitokondride ATP sentazın baş kısmının hangi bölmeye baktığı karşılaştırıldığında hangisi doğrudur?', 'Kloroplastta stromaya, mitokondride matrikse bakar', ['İkisinde de zarlar arası boşluğa bakar', 'Kloroplastta tilakoit içine, mitokondride sitozole bakar', 'İkisinde de hücre dışına bakar'], 'İki organelde de ATP, protonların içinden geçtiği ATP sentazın baş kısmının bulunduğu iç bölmede (kloroplastta stroma, mitokondride matriks) üretilir.'),
  ('Faz kontrast mikroskobunu geliştirerek boyasız canlı hücrelerin incelenmesini kolaylaştıran ve bu buluşla 1953 Nobel Fizik Ödülü\'nü alan bilim insanı kimdir?', 'Frits Zernike', ['Ernst Ruska', 'Robert Brown', 'Anton van Leeuwenhoek'], 'Hollandalı fizikçi Frits Zernike\'nin faz kontrast yöntemi, saydam yapıların neden olduğu faz farklarını parlaklık farkına çevirir.'),
  ('Hücrede ipliksi ve tanecikli görünen yapılara 1898\'de Yunanca "iplik" ve "tanecik" sözcüklerinden türeyen "mitokondri" adını veren bilim insanı kimdir?', 'Carl Benda', ['Robert Brown', 'Camillo Golgi', 'Christian de Duve'], 'Alman mikrobiyolog Carl Benda bu organelleri boyayarak incelemiş ve mitos (iplik) ile khondrion (tanecik) sözcüklerinden mitokondri adını türetmiştir.'),
  ('Kuşak biçiminde hücreyi saran, kaderinler aracılığıyla komşu hücrelere tutunan ve hücre içinde aktin ipliklerine bağlanan hücre bağlantısına ne ad verilir?', 'Yapışma kuşağı', ['Hemidesmozom', 'Geçit bağlantısı', 'Plazmodezma'], 'Aderens bağlantıları hücreyi bir kuşak gibi sarar; aktin demetlerine bağlı olduklarından epitel tabakasının biçim değiştirmesinde ve katlanmasında rol oynar.'),
  ('Komşu iki epitel hücresinin zarlarını sıkıca birbirine dikerek sıkı bağlantıyı oluşturan transmembran proteinlerin başlıcaları hangileridir?', 'Klaudinler ve okludin', ['Konneksinler', 'Klatrinler', 'Histonlar'], 'Sıkı bağlantılar komşu zarlardaki klaudin ve okludin proteinlerinin sıralar hâlinde birbirine kenetlenmesiyle oluşur; bu sıralar hücreler arası boşluğu kapatır.'),
  ('Arkelerin ve pek çok bakterinin en dış yüzeyinde bulunabilen, protein ya da glikoprotein alt birimlerinin düzenli bir kafes gibi dizilmesiyle oluşan tabakaya ne ad verilir?', 'S tabakası', ['Kapsül', 'Dış zar', 'Orta lamel'], 'S tabakası tek tip protein alt birimlerinin kristal benzeri düzenle dizildiği bir yüzey katmanıdır; birçok arkede çeperin tek bileşeni olarak hücreye biçim ve koruma sağlar.'),
  ('Hücre zarının küçük bir parçasına cam bir pipet ucunu yapıştırarak tek bir iyon kanalından geçen akımın ölçülmesini sağlayan ve 1991 Nobel Ödülü\'ne konu olan yönteme ne ad verilir?', 'Yama kenetleme', ['Diferansiyel santrifüj', 'Dondurarak kırma', 'Kâğıt kromatografisi'], 'Neher ve Sakmann\'ın geliştirdiği yöntemle tek tek kanalların açılıp kapanması akım sıçramaları olarak kaydedilebilmiş, iyon kanallarının varlığı doğrudan kanıtlanmıştır.'),
  ('Alzheimer hastalığında sinir hücrelerinde normalde mikrotübülleri kararlı tutan bir proteinin aşırı fosfat bağlayarak yumak oluşturduğu görülür. Bu protein hangisidir?', 'Tau', ['Aktin', 'Klatrin', 'Keratin'], 'Tau proteini aksonlardaki mikrotübüllere bağlanıp onları kararlı tutar; aşırı fosforlandığında mikrotübüllerden ayrılır, içi yumaklar hâlinde birikir ve aksonal taşıma bozulur.'),
  ('400 kat büyütmede bir oküler mikrometrenin 4 bölmesinin, objektif mikrometresinin 10 µm\'lik tek bir bölmesine denk geldiği bulunuyor. Aynı büyütmede 12 oküler bölmesi uzunluğundaki bir hücrenin gerçek uzunluğu kaç µm\'dir?', '30 µm', ['12 µm', '48 µm', '120 µm'], 'Bir oküler bölmesi 10 / 4 = 2,5 µm\'ye karşılık gelir. Hücre 12 × 2,5 = 30 µm uzunluğundadır.'),
  ('Bir bitki hücresinde nitrat alımının dış ortamın pH\'ı düşürüldüğünde (H⁺ derişimi artırıldığında) hızlandığı gözleniyor. Bu gözlem en iyi hangi taşıma biçimiyle açıklanır?', 'H⁺ ile birlikte ortak taşıma', ['Nitratın basit difüzyonu', 'Nitratın ekzositozu', 'Nitratın kanal proteiniyle dışarı atılması'], 'Dışarıda H⁺ artınca protonların içeri akma eğilimi güçlenir; nitrat protonlarla birlikte içeri alındığı için alım hızlanır.'),
  ('Böbreküstü bezi kabuğu gibi steroit hormon üreten hücrelerin mitokondrilerinde kristaların yaygın yassı levhalar yerine farklı bir biçimde olduğu görülür. Bu biçim hangisidir?', 'Boru biçimli kristalar', ['Kristaların tamamen kaybolması', 'Çok sayıda tilakoit yığını', 'Kristaların hiç bulunmayıp matriksin boş kalması'], 'Steroit üreten hücrelerde mitokondriler boru (tübüler) biçimli kristalar taşır; bu mitokondriler steroit sentezinin bazı basamaklarını da yürütür.'),
  ('Lökoplastlar depoladıkları maddeye göre adlandırılır. Yağ depolayan lökoplastlara ne ad verilir?', 'Elayoplast', ['Amiloplast', 'Proteinoplast', 'Kromoplast'], 'Nişasta depolayan lökoplastlar amiloplast, protein depolayanlar proteinoplast, yağ depolayanlar ise elayoplast olarak adlandırılır.'),
  ('Bitkilerde yaralanma ya da zorlanma durumunda plazmodezmaların ve kalburlu boru gözeneklerinin hızla tıkanmasını sağlayan polisakkarit hangisidir?', 'Kaloz', ['Selüloz', 'Lignin', 'Pektin'], 'Kaloz bir glikoz polimeridir; gerektiğinde plazmodezma ağızlarında ve kalbur levhalarında hızla birikerek geçişi kapatır, böylece öz su kaybı ve patojen yayılımı sınırlanır.'),
  ('Bazı siyanobakteri ipliklerinde, azot fiksasyonu yapan enzimi oksijenden korumak için kalın çeperli ve fotosentezin oksijen üreten kısmı çalışmayan özel hücreler bulunur. Bu hücrelere ne ad verilir?', 'Heterosist', ['Akinet', 'Nükleoit', 'Endospor'], 'Heterosistlerde oksijen üreten fotosistem çalışmaz ve kalın çeper oksijen girişini sınırlar; böylece oksijene duyarlı nitrojenaz enzimi azot bağlayabilir.'),
  ('Işık mikroskobunun ayırma sınırı yaklaşık d = λ / (2 × NA) ile hesaplanır. Dalga boyu 500 nm olan ışık ve sayısal açıklığı (NA) 1,25 olan bir objektif kullanılırsa ayırma sınırı yaklaşık kaç nm olur?', '200 nm', ['625 nm', '400 nm', '1250 nm'], 'd = 500 / (2 × 1,25) = 500 / 2,5 = 200 nm, yani yaklaşık 0,2 µm.'),
  ('Bazı otototrof bakterilerde karbon tutan enzimin protein kabuklu çok yüzlü bölmelerde toplandığı görülür. Zarla çevrili olmayan bu bölmelere ne ad verilir?', 'Karboksizom', ['Manyetozom', 'Lizozom', 'Tilakoit'], 'Karboksizomların protein kabuğu, karbon tutan enzimin çevresinde CO₂\'yi yoğunlaştırarak verimini artırır; prokaryotlarda zarsız bölmeleşmenin bir örneğidir.'),
  ('Spiroketler adlı sarmal bakterilerde kamçılar hücre dışına uzanmak yerine hücre zarı ile dış kılıf arasında hücreyi boydan boya sarar. Bu düzenlemenin bakteriye sağladığı yarar nedir?', 'Burgu gibi dönerek ilerlemek', ['Fotosentez yapabilmek', 'Konak hücre çekirdeğine girmek', 'Hücre duvarını tamamen ortadan kaldırıp konak hücreyle kaynaşmak'], 'İç kamçılar dönerken bütün hücre bir burgu gibi kıvrılır; bu, sifiliz ve Lyme hastalığı etkenleri gibi spiroketlerin dokular ve yoğun sıvılar içinde ilerlemesini sağlar.'),
  ('Kemik iliği kanserlerinden multipl miyelomda kullanılan bazı ilaçlar proteazomu engeller. Bol miktarda antikor salgılayan bu kanser hücrelerinin ilaca duyarlı olmasının nedeni nedir?', 'Bozuk proteinlerin birikmesi', ['Proteazomlarının DNA\'larını kopyalaması', 'İlacın yalnız mitokondrilerde birikmesi', 'Hücre duvarlarının ilaçla erimesi'], 'Bu hücreler çok fazla protein ürettiğinden yanlış katlanan proteinleri sürekli proteazomda yıkmak zorundadır; proteazom engellenince bozuk proteinler birikir ve hücreler ölür.'),
  ('Klamidomonas gibi tek hücreli yeşil alglerin kase biçimli kloroplastında bulunan ve nişasta oluşumunun merkezi olan protein yoğun bölgeye ne ad verilir?', 'Pirenoit', ['Granum', 'Nükleoit', 'Tonoplast'], 'Pirenoitler pek çok algin kloroplastında bulunur; karbon tutan enzimin yoğunlaştığı bu bölgenin çevresinde nişasta birikir.'),
  ('Bağırsak paraziti Giardia gibi bazı oksijensiz ortamda yaşayan ökaryotlarda tipik mitokondri görülmez; ancak mitozom denen küçük çift zarlı organeller bulunur. Bu bulgu için en doğru yorum hangisidir?', 'Organel atadan kalmış, küçülmüştür', ['Bu canlılar hiçbir zaman mitokondrili bir atadan gelmemiştir', 'Mitozomlar kloroplastın kalıntısıdır', 'Mitozomlar bu canlıların çekirdeğidir'], 'Mitozomlar mitokondri kökenli proteinler taşır; bu, söz konusu canlıların mitokondrili atalardan geldiğini ve oksijensiz yaşama uyum sırasında organelin küçüldüğünü gösterir.'),
  ('Rubisko enziminin büyük alt birimi kloroplast DNA\'sında, küçük alt birimi ise çekirdek DNA\'sında şifrelenir. Bu durum neyi gösterir?', 'Kloroplastın işlevinin iki genomun iş birliğine bağlı olduğunu', ['Kloroplastın çekirdekten tamamen bağımsız olduğunu', 'Çekirdeğin kloroplast içinde bulunduğunu', 'Rubiskonun yalnız sitoplazmada çalıştığını'], 'Küçük alt birim sitoplazmada yapılıp kloroplasta aktarılır ve stromada büyük alt birimle birleşir; organel işlevleri iki genomun eşgüdümüyle yürür.'),
  ('Bir öğrenci "Arke ve bakteri kamçıları aynı yapıdadır, çünkü ikisi de prokaryottur" diyor. Bu görüş için doğru değerlendirme hangisidir?', 'Yanlıştır; arke kamçıları yapı ve enerji kaynağı bakımından bakterilerinkinden farklıdır', ['Doğrudur; bütün prokaryot kamçıları tıpatıp aynıdır', 'Doğrudur; arkelerin kamçısı ökaryotlarınkiyle aynıdır', 'Yanlıştır; arkelerde hiç kamçı bulunmaz'], 'Arke kamçısı bakteri kamçısına benzer biçimde döner ama farklı proteinlerden yapılır ve ATP ile çalışır; yapısal olarak bazı bakteri pililerine daha yakındır.'),
  ('Peroksizomların protein alma biçimini mitokondrilerinkinden ayıran ilginç bir özellik hangisidir?', 'Katlanmış proteinleri de alabilmeleri', ['Proteinlerini kendi DNA\'larından üretmeleri', 'Proteinleri yalnız Golgi\'den gelen salgı keseciklerinden almaları', 'Hiç protein almamaları'], 'Mitokondriye aktarılacak proteinler zar kanallarından geçebilmek için açılmış hâlde olmalıdır; peroksizomlar ise katlanmış ve birden çok alt birimden oluşan proteinleri bile içeri alabilir.'),
  ('Bakteri çeperindeki peptidoglikanın yapısı için hangisi doğrudur?', 'Peptit köprüleriyle bağlı şeker zincirleri ağı', ['Yalnızca amino asitlerden oluşan tek bir uzun zincir', 'Fosfolipitlerden oluşan, proteinlerle süslü çift katlı bir zar', 'Selüloz liflerinin pektinle yapıştırılmasıyla oluşan tabaka'], 'Peptidoglikan, iki farklı amino şekerin dönüşümlü dizildiği zincirlerin kısa peptitlerle çapraz bağlanmasıyla oluşan, hücreyi saran ağ biçiminde tek bir dev moleküldür.'),
  ('Aktin ipliklerinin bir ucundan sürekli alt birim eklenirken öbür ucundan aynı hızda alt birim kopmasıyla ipliğin boyu değişmeden alt birimlerin iplik boyunca ilerlemesine ne ad verilir?', 'Yürüme bandı hareketi', ['Dinamik kararsızlık', 'Plazmoliz', 'Sitokinez'], 'Bu olayda iplik boyu sabit kalsa da alt birimler bir uçtan girip öbür uçtan çıkar; hücre ön kenarındaki aktin ağının ilerlemesinde önemlidir.'),
  ('Transmisyon elektron mikroskobunda hücre zarı yüksek büyütmede koyu-açık-koyu üç çizgi gibi görünür. Bu görüntünün yapısal karşılığı nedir?', 'Koyu çizgiler başlar, açık bant kuyruklardır', ['Üç ayrı zarın üst üste binmesi', 'Koyu çizgiler kolesterol molekülleri, açık bant ise zar proteinleridir', 'Ortadaki açık bant zarın içindeki boşluktur'], 'Ağır metal boyalar fosfolipitlerin polar başlarına ve yüzey proteinlerine bağlanıp koyu görünür; aradaki apolar kuyruk bölgesi boya tutmadığından açık kalır.'),
  ('Kinezin molekülü mikrotübül üzerinde ilerlerken iki "baş" kısmını sırayla öne atar. Bu hareket en iyi nasıl tanımlanır?', 'İki başın dönüşümlü bağlanıp ayrılarak adım atması', ['Molekülün mikrotübül boyunca kayarak sürüklenmesi', 'Mikrotübülün kinezini iterek fırlatması', 'Kinezinin her adımda yeniden sentezlenmesi'], 'Kinezinin bir başı mikrotübüle bağlıyken diğeri ATP\'nin yıkımıyla öne savrulur ve bağlanır; iki ayaklı bir yürüyüşe benzeyen bu düzen yükün kopmadan uzun mesafe taşınmasını sağlar.'),
  ('Peroksizomların hücrede çoğalma biçimleri için günümüzde kabul edilen görüş hangisidir?', 'Bölünmeyle ve ER kökenli keseciklerden', ['Yalnızca çekirdek zarından tomurcuklanarak oluşan keseciklerden', 'Mitokondrilerin parçalanmasıyla oluşurlar', 'Hücre dışından endositozla alınırlar'], 'Peroksizomlar büyüyüp bölünerek çoğalabilir; peroksizom hiç kalmamış hücrelerde ise ER\'den köken alan öncül keseciklerle yeniden oluşturulabilir.'),
  ('Bitki hücrelerinde merkezi kofulun zarında da bol miktarda akuaporin bulunur. Bunun hücreye sağladığı yarar hangisidir?', 'Kofulun sitoplazma hacmini tamponlaması', ['Kofula hiç su girmemesi', 'Kofulun sindirim enzimlerini hücre dışına hızla atabilmesi', 'Kofulun fotosentez yapabilmesi'], 'Tonoplasttaki su kanalları büyük kofulun bir tampon gibi çalışmasını sağlar; ortam değiştiğinde su önce kofuldan çekilir ya da kofula girer ve sitoplazma hacmi korunur.'),
  ('Bakteri ribozomlarının kütlesinin yaklaşık üçte ikisini hangi bileşen oluşturur?', 'rRNA', ['Ribozomal proteinler', 'Lipitler', 'DNA'], 'Bakteri ribozomlarında kütlenin yaklaşık üçte ikisi rRNA\'dan, geri kalanı onlarca farklı proteinden oluşur; bu da RNA\'nın ribozomdaki temel rolünü gösterir.'),
  ('Büyük merkezi kofulu olan bitki hücrelerinde sitoplazmanın hücre zarının hemen altında ince bir tabaka hâlinde bulunması madde alışverişi açısından ne sağlar?', 'Sitoplazmanın zara yakın kalması', ['Hücrenin hiç madde alışverişi yapmaması', 'Sitoplazmanın kofulla karışıp tek bir sıvı bölme oluşturması', 'Hücre duvarının ortadan kalkması'], 'Koful hacmin büyük kısmını kapladığı için etkin sitoplazma ince bir katmana yayılır; böylece büyük bir hücre bile madde alışverişinde küçük bir hücre gibi davranır.'),
  ('Epitel hücreleri bulundukları bazal laminadan koparılıp askıda kalacak biçimde kültürlendiğinde kısa sürede programlı ölüme gider. Bu durum integrinlerle ilgili hangi bilgiyi destekler?', 'Zemine tutunmanın hücreye hayatta kalma sinyali verdiği', ['İntegrinlerin hücreye besin taşıdığı', 'İntegrinlerin DNA\'yı eşlediği', 'Tutunmanın hücre bölünmesini her zaman durdurduğu'], 'İntegrinler matrikse bağlandığında hücre içine yaşamsal sinyaller iletir; bu sinyal kesilince hücre apoptoza gider. Bu düzenek hücrelerin yanlış yerde çoğalmasını engeller.'),
];
